BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT114-S2-Q15$batch04$ AND q.stimulus=$batch04$Ashley: Words like “of” and “upon,” unlike “pencil” and “shirt,” do not refer to anything.Joshua: I agree; and since such words are meaningless, they should be abandoned.$batch04$ AND q.prompt=$batch04$Joshua's remarks indicate that he interpreted Ashley's statement to imply that$batch04$ AND q.correct_choice=$batch04$A$batch04$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT114-S2-Q15$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT114-S2-Q15$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$(Joshua) Words like "of" and "upon" should be abandoned.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$(Joshua) Such words are meaningless, which he draws from Ashley's statement that they do not refer to anything.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Ashley said these words do not *refer* to anything. Joshua jumped to "meaningless." That jump only works if a word needs to refer in order to have meaning.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: if a word does not refer to anything, it has no meaning.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT114-S2-Q15$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Negate it: words that refer to *nothing* can still have meaning. Then Ashley's statement does not make "of" and "upon" meaningless, and Joshua's reading falls apart.$batch04$), ($batch04$B$batch04$, $batch04$Joshua never talks about usefulness.$batch04$), ($batch04$C$batch04$, $batch04$This says referring words have meaning. Joshua needs the reverse: words that do not refer have none.$batch04$), ($batch04$D$batch04$, $batch04$Joshua's reason for abandoning the words is that they are meaningless, not that they are not useful.$batch04$), ($batch04$E$batch04$, $batch04$Usefulness is never part of Joshua's reasoning.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT114-S2-Q15$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
